        text='Солнце ещё на протяжении 5 миллиардов лет будет светить как звезда главной последовательности, постепенно увеличивая свою светимость на 10\\% каждый миллиард лет.\n1) Определите светимость Солнца перед превращением его в красный гигант (в единицах современной светимости L0).\n2) Как далеко сдвинется зона жизни (зона обитаемости) в Солнечной системе к концу жизни Солнца? Принять текущие границы зоны жизни 0.8–1.1 а.е.\n3) Текущая потеря массы Солнцем примерно 5·10$^{-12}$ масс Солнца в год. Если предположить, что рост темпа потери массы будет таким же, как и рост светимости, какую часть массы Солнце потеряет до превращения в красный гигант?\n4) Сравните полученный результат с изменением массы Солнца за счёт явления дефекта массы в термоядерных реакциях.\n\nСтадия красного гиганта для Солнца продолжится на протяжении 100 миллионов лет, пока постепенно не рассеется вся оболочка звезды, а Солнце не превратится в белый карлик массой 0.6 современной массы Солнца.\n5) Определите скорость потери массы Солнцем (в массах Солнца в год) на этом этапе.\n6) Определите, во сколько раз изменился радиус орбит уцелевших планет.',
