        subtopic='Задачи на схему затмения',
        text='11 февраля 2017 года отмечено не только проведением 71-й Московской астрономической олимпиады, но и полутеневым лунным затмением.\n\nСхема затмения. Две тёмные концентрические окружности показывают тень и полутень Земли. Три малые окружности соответствуют положению Луны в начале, середине и конце затмения. Длинной горизонтальной линией обозначена линия эклиптики, стороны света отмечены короткими штрихами на краях полутени. Максимальная фаза полутеневого затмения: 0.9884. Максимальная фаза теневого затмения: −0.0354. (Фазой затмения называют долю диаметра Луны, закрытую затмевающим «объектом»: тенью или полутенью.)\n\nСобытие: начало полутеневого затмения — 22:34 UTC (10 февраля); максимальное затмение — 00:44 UTC; конец полутеневого затмения — 02:53 UTC (11 февраля).\n\nВо время полутеневого затмения Луна не попадает в тень Земли. Луна пройдёт восходящий узел орбиты 11 февраля в 19:50 по UTC.\n\n1. Вам представлено 6 фотографий, на одной (или нескольких) из которых изображена Луна в фазе полутеневого затмения (конечно, среди них нет фотографии сегодняшнего затмения). Укажите эту(и) фотографию(и) и объясните, почему Вы так решили. Также объясните, почему на остальных фотографиях Луна не находится в фазе полутеневого затмения.\n2. С какой стороны (сверху/снизу/справа/слева) на схеме затмения находится направление на север?\n3. В каких созвездиях находятся Земля и Солнце для наблюдателя, находящегося вблизи Северного полюса Луны (считайте, что небесные тела находятся выше линии местного лунного горизонта)?\n4. Пользуясь данными из условия, определите, где на Земле можно было наблюдать данное затмение. Считайте, что метеорологические условия не препятствовали наблюдениям.\nа) Северный полюс (90° с.ш.)\nб) Сан-Томе (0° с.ш., 7° в.д.)\nв) Науру (1° ю.ш., 167° в.д.)\nг) Южный полюс (90° ю.ш.)\n5. Определите минимальную высоту спутника на окололунной орбите, который мог бы попасть в зону видимости полного солнечного затмения.\n\n[изображение — схема затмения и 6 фотографий Луны — отсутствует в исходном файле]',
